create or replace function public.freq_next(f text, d date) returns date language sql immutable as $$
  select case f
    when 'daily' then d + 1 when 'weekly' then d + 7 when 'fortnightly' then d + 14 when 'four_weekly' then d + 28
    when 'monthly' then (d + interval '1 month')::date when 'quarterly' then (d + interval '3 months')::date
    when 'six_monthly' then (d + interval '6 months')::date when 'yearly' then (d + interval '12 months')::date
    when 'fourteen_months' then (d + interval '14 months')::date when 'two_yearly' then (d + interval '24 months')::date
    when 'twenty_six_months' then (d + interval '26 months')::date when 'three_yearly' then (d + interval '36 months')::date
    when 'five_yearly' then (d + interval '60 months')::date else null end $$;

