create or replace function public.practice_inputs(p_practice uuid) returns jsonb
language plpgsql security definer set search_path = public as
$$
declare aid uuid; res jsonb; r public.user_role;
begin
  if not public.can_read_practice(p_practice) then raise exception 'Not permitted'; end if;
  r := public.auth_role();
  if r in ('group_admin','inspector','platform_admin') then
    perform public.log_event('view_dashboard','practice',p_practice::text,p_practice,'{}'::jsonb);
  end if;
  select id into aid from public.assessments
   where practice_id = p_practice and status = 'completed' and kind = 'hiw' order by completed_at desc limit 1;
  select jsonb_build_object(
    'practice', (select to_jsonb(p) from public.practices p where p.id = p_practice),
    'evidence', coalesce((select jsonb_agg(jsonb_build_object(
                  'category',category,'status',status,'expiry_date',expiry_date))
                  from public.evidence where practice_id = p_practice), '[]'::jsonb),
    'assessment', case when aid is null then null else jsonb_build_object(
        'id', aid,
        'completed_at', (select completed_at from public.assessments where id = aid),
        'answers', coalesce((select jsonb_agg(jsonb_build_object('category',q.category,'answer',a.answer))
                    from public.assessment_answers a
                    join public.assessment_questions q on q.id = a.question_id
                    where a.assessment_id = aid), '[]'::jsonb)) end,
    'training', coalesce((select jsonb_agg(jsonb_build_object('kind',m.kind,'status',t.status))
                  from public.training_assignments t
                  join public.training_modules m on m.id = t.module_id
                  where t.practice_id = p_practice), '[]'::jsonb),
    'staff_count', (select count(*) from public.profiles
                     where practice_id = p_practice and active and role in ('staff','practice_manager','principal')),
    'pm_trained', exists (select 1 from public.training_assignments t
                  join public.training_modules m on m.id = t.module_id
                  where t.practice_id = p_practice and m.kind = 'pm' and t.status = 'completed'),
    'snapshots', coalesce((select jsonb_agg(jsonb_build_object('taken_on',taken_on,'score',score) order by taken_on)
                  from public.compliance_snapshots
                  where practice_id = p_practice and taken_on > current_date - 190), '[]'::jsonb)
  ) into res;
  return res;
end $$;


-- ---------- recurring tasks ----------
create table if not exists public.practice_tasks (
  id uuid primary key default gen_random_uuid(),
  practice_id uuid not null references public.practices(id) on delete cascade,
  title text not null, title_cy text, category text,
  frequency text not null check (frequency in ('once','daily','weekly','fortnightly','four_weekly','monthly','quarterly','six_monthly','yearly','fourteen_months','two_yearly','twenty_six_months','three_yearly','five_yearly')),
  assignee_id uuid references public.profiles(id) on delete set null,
  next_due date not null, last_done date, active boolean not null default true, notes text,
  created_by uuid, created_at timestamptz not null default now()
);
create index if not exists practice_tasks_practice_idx on public.practice_tasks(practice_id, next_due);
create table if not exists public.task_completions (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references public.practice_tasks(id) on delete cascade,
  practice_id uuid not null references public.practices(id) on delete cascade,
  due_date date, done_on date not null default current_date, done_by uuid, note text,
  created_at timestamptz not null default now()
);
create index if not exists task_completions_task_idx on public.task_completions(task_id, done_on desc);
alter table public.practice_tasks enable row level security;
alter table public.task_completions enable row level security;

create or replace function public.task_guard() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is not null and tg_op = 'INSERT' then new.created_by := auth.uid(); end if;
  if new.assignee_id is not null and not exists (select 1 from public.profiles p where p.id = new.assignee_id and p.practice_id = new.practice_id) then
    raise exception 'Assignee must belong to the practice';
  end if;
  return new;
end $$;
drop trigger if exists practice_tasks_guard on public.practice_tasks;
create trigger practice_tasks_guard before insert or update on public.practice_tasks for each row execute function public.task_guard();

drop policy if exists tasks_select on public.practice_tasks;
create policy tasks_select on public.practice_tasks for select to authenticated using (
  public.can_manage_practice(practice_id) or public.is_group_admin_of(practice_id) or assignee_id = auth.uid());
drop policy if exists tasks_write on public.practice_tasks;
create policy tasks_write on public.practice_tasks for all to authenticated
  using (public.can_book(practice_id)) with check (public.can_book(practice_id));
drop policy if exists completions_select on public.task_completions;
create policy completions_select on public.task_completions for select to authenticated using (
  public.can_manage_practice(practice_id) or public.is_group_admin_of(practice_id) or done_by = auth.uid());

create or replace function public.complete_task(p_task uuid, p_note text default null) returns date
language plpgsql security definer set search_path = public as $$
declare t public.practice_tasks%rowtype; nxt date; n int := 0;
begin
  select * into t from public.practice_tasks where id = p_task and active;
  if not found then raise exception 'Task not found'; end if;
  if not coalesce(public.can_manage_practice(t.practice_id)
          or (t.assignee_id is not null and t.assignee_id = auth.uid()
              and exists (select 1 from public.profiles p where p.id = auth.uid() and p.active)), false) then
    raise exception 'Not permitted';
  end if;
  insert into public.task_completions(task_id, practice_id, due_date, done_by, note) values (t.id, t.practice_id, t.next_due, auth.uid(), p_note);
  if t.frequency = 'once' then
    update public.practice_tasks set last_done = current_date, active = false where id = t.id; return null;
  end if;
  nxt := public.freq_next(t.frequency, t.next_due);
  while nxt <= current_date and n < 400 loop nxt := public.freq_next(t.frequency, nxt); n := n + 1; end loop;
  update public.practice_tasks set last_done = current_date, next_due = nxt where id = t.id;
  perform public.log_event('complete_task', 'task', t.id::text, t.practice_id, jsonb_build_object('title', t.title));
  return nxt;
end $$;
revoke execute on function public.complete_task(uuid, text) from public, anon;

-- ---------- maintenance register ----------
create table if not exists public.maintenance_items (
  id uuid primary key default gen_random_uuid(),
  practice_id uuid not null references public.practices(id) on delete cascade,
  grp text, name text not null, name_cy text,
  frequency text not null check (frequency in ('once','daily','weekly','fortnightly','four_weekly','monthly','quarterly','six_monthly','yearly','fourteen_months','two_yearly','twenty_six_months','three_yearly','five_yearly')),
  last_done date, next_due date, notes text, active boolean not null default true,
  updated_at timestamptz not null default now()
);
create index if not exists maintenance_practice_idx on public.maintenance_items(practice_id, next_due);
alter table public.maintenance_items enable row level security;
create or replace function public.maintenance_next() returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  if new.last_done is not null and new.frequency <> 'once' then new.next_due := public.freq_next(new.frequency, new.last_done); end if;
  if new.frequency = 'once' and new.last_done is not null then new.next_due := null; end if;
  return new;
end $$;
drop trigger if exists maintenance_next on public.maintenance_items;
create trigger maintenance_next before insert or update on public.maintenance_items for each row execute function public.maintenance_next();
drop policy if exists maintenance_select on public.maintenance_items;
create policy maintenance_select on public.maintenance_items for select to authenticated using (
  public.can_manage_practice(practice_id) or public.is_group_admin_of(practice_id) or public.has_inspector_grant(practice_id));
drop policy if exists maintenance_write on public.maintenance_items;
create policy maintenance_write on public.maintenance_items for all to authenticated
  using (public.can_manage_practice(practice_id)) with check (public.can_manage_practice(practice_id));

-- ---------- digital logs (insert-only) ----------
create table if not exists public.log_entries (
  id uuid primary key default gen_random_uuid(),
  practice_id uuid not null references public.practices(id) on delete cascade,
  log_type text not null check (log_type in ('autoclave','washer','emergency','fridge','legionella','xray')),
  entry_date date not null default current_date,
  data jsonb not null default '{}'::jsonb,
  pass boolean not null default true, note text,
  done_by uuid, created_at timestamptz not null default now()
);
create index if not exists log_entries_idx on public.log_entries(practice_id, log_type, entry_date desc);
alter table public.log_entries enable row level security;
create or replace function public.log_entry_guard() returns trigger language plpgsql as $$
begin if auth.uid() is not null then new.done_by := auth.uid(); end if; return new; end $$;
drop trigger if exists log_entry_guard on public.log_entries;
create trigger log_entry_guard before insert on public.log_entries for each row execute function public.log_entry_guard();
drop policy if exists logs_select on public.log_entries;
create policy logs_select on public.log_entries for select to authenticated using (public.can_read_practice(practice_id));
drop policy if exists logs_insert on public.log_entries;
create policy logs_insert on public.log_entries for insert to authenticated with check (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.active
          and p.role in ('principal','practice_manager','staff') and p.practice_id = log_entries.practice_id));

-- ---------- policy library + sign-off ----------
create table if not exists public.policies (
  id serial primary key, ref text unique not null, folder text, title_en text not null, title_cy text,
  body_en text, version int not null default 1, updated_on date not null default current_date
);
alter table public.policies enable row level security;
drop policy if exists policies_select on public.policies;
create policy policies_select on public.policies for select to authenticated using (true);
drop policy if exists policies_admin on public.policies;
create policy policies_admin on public.policies for all to authenticated
  using (public.auth_role() = 'platform_admin') with check (public.auth_role() = 'platform_admin');
create table if not exists public.policy_reviews (
  policy_id int not null references public.policies(id) on delete cascade,
  profile_id uuid not null references public.profiles(id) on delete cascade,
  practice_id uuid not null references public.practices(id) on delete cascade,
  version int not null, reviewed_at timestamptz not null default now(),
  primary key (policy_id, profile_id, version)
);
alter table public.policy_reviews enable row level security;
drop policy if exists reviews_select on public.policy_reviews;
create policy reviews_select on public.policy_reviews for select to authenticated using (
  profile_id = auth.uid() or public.can_manage_practice(practice_id) or public.is_group_admin_of(practice_id));
drop policy if exists reviews_insert on public.policy_reviews;
create policy reviews_insert on public.policy_reviews for insert to authenticated with check (
  profile_id = auth.uid()
  and practice_id = (select p.practice_id from public.profiles p where p.id = auth.uid() and p.active)
  and version = (select v.version from public.policies v where v.id = policy_id));
insert into public.policies (ref, folder, title_en, title_cy, body_en) values
('POL01','Governance','Complaints policy','Polisi cwynion','Purpose: to make sure every concern is listened to, recorded and learned from.
How it works: patients can complain in person, by phone, in writing or by e-mail, in English or Welsh. We acknowledge a complaint within 2 working days and aim to give a full response within 30 working days, in line with ''Putting Things Right''. Private patients are also given HIW''s contact details.
Recording: every complaint, including verbal and informal concerns, is entered in the complaints log with the action taken.
Learning: themes are reviewed at the monthly team meeting.
Responsible person: [name], Registered Manager.'),
('POL02','Governance','Raising concerns (whistleblowing) policy','Polisi codi pryderon (chwythu''r chwiban)','Purpose: staff are encouraged to raise concerns about patient safety or malpractice without fear of reprisal.
How: speak to [name]; if that is not appropriate, speak to the Principal, the GDC, HIW or Protect (the whistleblowing charity).
The practice will acknowledge a concern within 5 working days, investigate it fairly and keep the person informed. Staff who raise concerns in good faith will not be disadvantaged.'),
('POL03','Safeguarding','Safeguarding children and adults policy','Polisi diogelu plant ac oedolion','Purpose: to protect children and adults at risk.
Safeguarding lead: [name]. All staff complete safeguarding training appropriate to their role and refresh it at least every 3 years.
If you have a concern: tell the safeguarding lead the same day, record facts only, and report to the local authority safeguarding team without delay. Never promise to keep a disclosure secret.
The Wales Safeguarding Procedures apply.'),
('POL04','Infection control','Infection prevention and control policy','Polisi atal a rheoli heintiau','Purpose: to reduce the risk of infection to patients and staff.
Standard precautions: hand hygiene using the practice''s 5 moments, PPE for every procedure, safe handling and disposal of sharps, surface cleaning between patients, and dental unit water line management.
Staff are immunised against Hepatitis B and records are kept.
An infection control audit is carried out at least every 6 months and actions are recorded.
Infection control lead: [name].'),
('POL05','Infection control','Decontamination policy (WHTM 01-05)','Polisi diheintio (WHTM 01-05)','Purpose: to make sure reusable instruments are safe to use.
Process: transport, clean (washer-disinfector preferred), inspect, sterilise, store and track. Dirty and clean areas are separated.
Records: daily and periodic tests of each autoclave and washer-disinfector are logged; equipment is validated and inspected in line with WHTM 01-05 (autoclave inspection at no more than 14-month intervals).
Staff doing decontamination are trained and training is recorded.
Decontamination lead: [name].'),
('POL06','Radiation','Radiation protection policy (IR(ME)R)','Polisi diogelu rhag ymbelydredd (IR(ME)R)','Purpose: to keep exposures as low as reasonably practicable and comply with IR(ME)R 2017 and the Ionising Radiations Regulations 2017.
Roles: Legal Person/employer [name]; Radiation Protection Supervisor [name]; Radiation Protection Adviser [name]; HSE notification held.
Every exposure must be justified, authorised and recorded. Local rules are displayed at each X-ray unit. Equipment is tested at the required intervals and image quality is audited. Staff holding IR(ME)R duties have documented training.'),
('POL07','Health & safety','Medical emergencies and resuscitation policy','Polisi argyfyngau meddygol ac adfywio','Purpose: to make sure the team can respond to a medical emergency.
All staff complete CPR/basic life support training every year, including anaphylaxis. A named first aider is on duty during opening hours.
Emergency drugs, oxygen (30 minutes'' supply minimum), suction and an AED are checked weekly and the checks are logged. Expired items are replaced.
In an emergency call 999, start CPR and fetch the AED.'),
('POL08','Health & safety','Health, safety and fire policy','Polisi iechyd, diogelwch a thân','Purpose: to provide a safe place to work and be treated.
We carry out and review risk assessments (including COSHH, manual handling, display screen equipment and workplace risk), keep an accident book (RIDDOR reportable events are reported to HSE), and keep PPE available.
Fire: a fire risk assessment is in place, alarms and emergency lighting are tested weekly, extinguishers are serviced yearly and drills take place at least every 6 months.
Health and safety lead: [name].'),
('POL09','Information governance','Data protection and confidentiality policy','Polisi diogelu data a chyfrinachedd','Purpose: to protect patient and staff personal data (UK GDPR, Data Protection Act 2018).
We collect only what we need, keep records secure (locked storage, passwords, off-site backup), share information only where permitted, and keep records for the retention periods in the NHS Records Management Code.
Patients can request their records; we respond within one month. Breaches are reported to [name] immediately and to the ICO within 72 hours where required.
Data protection lead: [name]. ICO registration is renewed every year.'),
('POL10','Clinical','Consent and mental capacity policy','Polisi cydsyniad a galluedd meddyliol','Purpose: to make sure treatment is only given with valid consent.
Patients are told the risks, benefits and alternatives (including no treatment) in a way they can understand and are given time to decide. Consent is recorded in the clinical notes. Capacity is assumed unless shown otherwise; where capacity is lacking, the Mental Capacity Act best-interests process is followed and recorded.'),
('POL11','Governance','Equality, diversity and Welsh language (Active Offer) policy','Polisi cydraddoldeb, amrywiaeth a''r Gymraeg (Cynnig Rhagweithiol)','Purpose: to treat everyone with dignity and fairness and meet the Equality Act 2010.
We make reasonable adjustments for disabled patients and staff, provide information in accessible formats, and offer services in Welsh proactively (the ''Active Offer''): patients are not expected to ask. Welsh-speaking staff are identified to patients where possible.
Discrimination, harassment or victimisation will not be tolerated.'),
('POL12','Health & safety','Waste management policy','Polisi rheoli gwastraff','Purpose: to dispose of waste safely and legally.
Waste is segregated at source into the correct colour-coded containers (clinical, sharps, amalgam, offensive/hygiene, extracted teeth, domestic). Amalgam separators are fitted and serviced. Waste is stored securely until collection by a licensed carrier and consignment notes are kept for the required period. Mercury spillages follow the spill procedure.'),
('POL13','Staffing','Recruitment, DBS and induction policy','Polisi recruitio, DBS a sefydlu','Purpose: to employ safe, suitable people.
Before starting: identity and right-to-work checks, two references, DBS check at the correct level, GDC registration and indemnity for registrants, immunisation history, and a signed contract.
Induction is completed in the first weeks and signed off by a manager. Appraisals take place every year and personal development plans are kept. Agency staff are checked for competence, training and DBS before they work.'),
('POL14','Clinical','Clinical record keeping policy','Polisi cadw cofnodion clinigol','Purpose: to keep accurate, complete and contemporaneous records (GDC Standards).
Every record shows patient identifiers, reason for attendance, symptoms, updated and signed medical history, examination and charting, BPE with action taken, treatment options and consent, treatment provided, radiograph justification and report, and recall interval. Records are audited at least yearly using a sample from each clinician.'),
('POL15','Governance','Business continuity policy','Polisi parhad busnes','Purpose: to keep patients safe and the practice running if something goes wrong (power, IT, water, fire, staff shortage).
Key contacts, alternative arrangements for emergency patients, IT backup and restore steps, and who decides to close are listed in the continuity plan. The plan is tested and reviewed yearly. Continuity lead: [name].')
on conflict (ref) do nothing;

-- ---------- per-person training / recruitment checklist ----------
create table if not exists public.hr_checklist (
  id uuid primary key default gen_random_uuid(),
  practice_id uuid not null references public.practices(id) on delete cascade,
  staff_id uuid not null references public.hr_staff(id) on delete cascade,
  kind text not null check (kind in ('training','recruitment')),
  item text not null,
  status text not null default 'done' check (status in ('done','na')),
  done_on date, note text,
  updated_by uuid, updated_at timestamptz not null default now(),
  unique (staff_id, kind, item)
);
alter table public.hr_checklist enable row level security;
create or replace function public.hr_checklist_guard() returns trigger language plpgsql as $$
begin new.updated_at := now(); if auth.uid() is not null then new.updated_by := auth.uid(); end if; return new; end $$;
drop trigger if exists hr_checklist_guard on public.hr_checklist;
create trigger hr_checklist_guard before insert or update on public.hr_checklist for each row execute function public.hr_checklist_guard();
drop trigger if exists hr_checklist_same on public.hr_checklist;
create trigger hr_checklist_same before insert or update on public.hr_checklist for each row execute function public.hr_same_practice();
drop policy if exists checklist_select on public.hr_checklist;
create policy checklist_select on public.hr_checklist for select to authenticated using (
  public.can_manage_practice(practice_id) or public.is_group_admin_of(practice_id) or staff_id = public.my_hr_staff_id());
drop policy if exists checklist_write on public.hr_checklist;
create policy checklist_write on public.hr_checklist for all to authenticated
  using (public.can_manage_practice(practice_id)) with check (public.can_manage_practice(practice_id));

-- ---------- alerts_due: now also tasks (due within 7 days / overdue) and maintenance ----------
create or replace function public.alerts_due(p_window int default 60)
returns table (profile_id uuid, email text, full_name text, language text, practice_id uuid, practice_name text,
               kind text, title text, who text, due_date date, days_left int, key text)
language sql stable security definer set search_path = public as $$
  with items as (
    select e.practice_id, 'evidence'::text as kind, e.title, coalesce(sp.full_name,'') as who, e.expiry_date as due,
           e.staff_member as owner, 'ev:'||e.id||':'||e.expiry_date as base
      from public.evidence e left join public.profiles sp on sp.id = e.staff_member
     where e.expiry_date is not null and e.status <> 'rejected'
    union all
    select h.practice_id, 'gdc', 'GDC registration', h.full_name, h.gdc_expiry, null, 'hr:'||h.id||':gdc:'||h.gdc_expiry
      from public.hr_staff h where h.active and h.gdc_expiry is not null
    union all
    select h.practice_id, 'indemnity', 'Indemnity', h.full_name, h.indemnity_expiry, null, 'hr:'||h.id||':indemnity:'||h.indemnity_expiry
      from public.hr_staff h where h.active and h.indemnity_expiry is not null
    union all
    select h.practice_id, 'dbs', 'DBS', h.full_name, h.dbs_expiry, null, 'hr:'||h.id||':dbs:'||h.dbs_expiry
      from public.hr_staff h where h.active and h.dbs_expiry is not null
    union all
    select a.practice_id, 'training', m.title_en, ap.full_name, a.due_date, a.profile_id, 'tr:'||a.id||':'||a.due_date
      from public.training_assignments a
      join public.training_modules m on m.id = a.module_id
      join public.profiles ap on ap.id = a.profile_id
     where a.status <> 'completed' and a.due_date is not null and a.due_date <= current_date + 14
    union all
    select t.practice_id, 'task', t.title, coalesce(tp.full_name,''), t.next_due, t.assignee_id, 'tk:'||t.id||':'||t.next_due
      from public.practice_tasks t left join public.profiles tp on tp.id = t.assignee_id
     where t.active and t.next_due <= current_date + 7 and t.frequency not in ('daily','weekly')
    union all
    select mi.practice_id, 'maintenance', mi.name, '', mi.next_due, null, 'mt:'||mi.id||':'||mi.next_due
      from public.maintenance_items mi where mi.active and mi.next_due is not null
  ), banded as (
    select i.*, (i.due - current_date) as dl,
           case when i.due < current_date then -1
                when i.due - current_date <= 0 then 0
                when i.due - current_date <= 14 then 14
                when i.due - current_date <= 30 then 30
                else 60 end as band
      from items i where i.due - current_date <= p_window
  )
  select r.id, r.email, r.full_name, r.language, b.practice_id, pr.name, b.kind, b.title, b.who, b.due, b.dl::int,
         b.base||':'||b.band
    from banded b
    join public.practices pr on pr.id = b.practice_id
    join public.profiles r on r.practice_id = b.practice_id and r.active
         and ( r.role in ('principal','practice_manager')
               or (r.role = 'staff' and b.owner = r.id and b.kind in ('evidence','training','task')) )
    left join public.alert_prefs ap on ap.profile_id = r.id
   where coalesce(ap.email_digest, true)
     and not exists (select 1 from public.alert_log l where l.profile_id = r.id and l.key = b.base||':'||b.band)
$$;
revoke execute on function public.alerts_due(int) from public, anon, authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.alerts_due(int) to service_role;
  end if;
end $$;
